* STAR1 -- SPACE INVADERS play field (transaction STAR). Mod 2, 24x80.
*
MAP STAR1 SIZE 24x80
  FIELD         AT 0,32  LEN 16 PROT BRIGHT COLOR=TURQUOISE " SPACE INVADERS "
  FIELD  PLNAME AT 1,34  LEN 20 PROT BRIGHT COLOR=BLUE
  
  FIELD  ROW02  AT 2,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW03  AT 3,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW04  AT 4,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW05  AT 5,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW06  AT 6,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW07  AT 7,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW08  AT 8,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW09  AT 9,0   LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW10  AT 10,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW11  AT 11,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW12  AT 12,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW13  AT 13,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW14  AT 14,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW15  AT 15,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW16  AT 16,0  LEN 60 PROT BRIGHT COLOR=RED
  FIELD  ROW17  AT 17,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW18  AT 18,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD  ROW19  AT 19,0  LEN 60 PROT BRIGHT COLOR=TURQUOISE
  FIELD  ROW20  AT 20,0  LEN 60 PROT BRIGHT COLOR=TURQUOISE

  FIELD  HSTITLE AT 3,62 LEN 12 PROT BRIGHT COLOR=NEUTRAL   "HIGH SCORES"
  FIELD  HS1     AT 5,61 LEN 15 PROT BRIGHT COLOR=GREEN
  FIELD  HS2     AT 6,61 LEN 15 PROT BRIGHT COLOR=GREEN
  FIELD  HS3     AT 7,61 LEN 15 PROT BRIGHT COLOR=GREEN

  FIELD         AT 21,0  LEN 60 PROT COLOR=BLUE "------------------------------------------------------------"
  FIELD  STATUS AT 22,0  LEN 60 PROT BRIGHT COLOR=GREEN
  FIELD         AT 23,0  LEN 55 PROT COLOR=BLUE "F1=Left  F3=Right  F2=Fire  F10=Pause  F12=Exit"

  INPUT  CMD    AT 23,70 LEN 1  UNPROT
  STOP          AT 23,72
  CURSOR        AT CMD
ENDMAP
